'use strict';
const $=s=>document.querySelector(s);
const E=(s='')=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=s=>{try{const u=new URL(s);return u.protocol==='https:'?u.href:'';}catch{return '';}};
const icons={
 table:'<path d="M4 4v6m3-6v6m-6-6v6q0 3 3 3v7m0-10h3M17 4v16m0-16q-4 4-3 10h3"/>',
 overview:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',
 venue:'<path d="M3 10l2-6h14l2 6M4 10v10h16V10M9 20v-6h6v6M3 10q3 5 6 0 3 5 6 0 3 5 6 0"/>',
 insights:'<path d="M4 4v16h16M8 15l4-5 4 2 4-7"/>',
 scan:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M7 7h3v3H7zm7 0h3v3h-3zM7 14h3v3H7zm7 0h3v3h-3z"/>',
 loyalty:'<rect x="3" y="8" width="18" height="4" rx="1"/><path d="M5 12v8h14v-8M12 8v12M12 8C3 8 5 1 9 4zm0 0c9 0 7-7 3-4z"/>',
 star:'<path d="M12 3l2.8 5.7 6.3.9-4.6 4.5 1.1 6.3-5.6-3-5.6 3 1.1-6.3L3 9.6l6.2-.9z"/>',
 wifi:'<path d="M2 8q10-9 20 0M5 12q7-6 14 0M8 16q4-3 8 0"/><circle cx="12" cy="20" r=".8"/>',
 feedback:'<path d="M21 11a8 8 0 0 1-8 8H7l-4 3V11a9 9 0 0 1 18 0zM7 11h10m-10 4h6"/>',
 menu:'<path d="M12 6Q6 2 3 4v15q4-2 9 1 5-3 9-1V4q-3-2-9 2zm0 0v14"/>',
};
const icon=(name)=>`<svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.table}</svg>`;
const brand=`<a class="brand" href="/restaurants/"><i>${icon('table')}</i><div>YAM Table<small>Made for hospitality</small></div></a>`;
let sb,user,profile,venues=[],feedback=[],members=[],events=[],selected=null,page='overview',tab='profile',guestPage='home',category='All',rating=0,card=null,busy=false;
const params=new URLSearchParams(location.search),slug=params.get('venue'),demo=slug==='demo',setupRequested=params.get('setup')==='1',agentDemo=params.get('agent-demo')==='1';
let setupStep=1;
const themes=window.restaurantThemes;
const adminDemo=params.get('admin-demo')==='1',managerDemo=params.get('manager-demo')==='1',localDemo=agentDemo||adminDemo||managerDemo;
let managerAccess=[],commissions=[],agentProfiles=[],isManager=false;
const isAdmin=()=>profile?.role==='admin'&&!isManager;
const canManage=(v=selected)=>!!v&&(isAdmin()||(!v.suspended&&(isManager?managerAccess.some(a=>a.venue_id===v.id&&a.user_id===user.id&&a.active):(v.owner_id===user.id&&v.agent_support!==false))));
const themeById=id=>themes.find(t=>t.id===id)||themes[0];
const agentName=id=>agentProfiles.find(p=>p.id===id)?.name||((id===user?.id)?profile?.name:null)||'Field agent';
async function manageApi(data){const session=check(await sb.auth.getSession()).session;const r=await fetch('/api/restaurant-manage',{method:'POST',headers:{'content-type':'application/json',Authorization:'Bearer '+session.access_token},body:JSON.stringify({venue_id:selected.id,...data})});const result=await r.json();if(!r.ok)throw Error(result.error);return result;}
async function allRows(table){const rows=[];for(let from=0;;from+=500){const chunk=check(await sb.from(table).select('*').order(table==='restaurant_venues'?'created_at':table==='restaurant_commissions'?'updated_at':'created_at',{ascending:false}).range(from,from+499));rows.push(...chunk);if(chunk.length<500)return rows;}}
const sampleMenu=[
 {id:'1',name:'Burrata & heirloom tomatoes',category:'Small plates',description:'Creamy burrata, basil oil, sourdough and a little sea salt.',price:420,diet:'Vegetarian',allergens:'Milk, gluten',image:'',available:true},
 {id:'2',name:'Wild mushroom toast',category:'Small plates',description:'Garlic mushrooms on toasted sourdough, finished with fresh herbs.',price:320,diet:'Vegetarian',allergens:'Gluten, milk',image:'',available:true},
 {id:'3',name:'Grilled chicken bowl',category:'Mains',description:'Herb-marinated chicken, warm grains, greens and lemon dressing.',price:490,diet:'',allergens:'Mustard',image:'',available:true},
 {id:'4',name:'Roasted vegetable pasta',category:'Mains',description:'Seasonal vegetables, slow-cooked tomato sauce and parmesan.',price:450,diet:'Vegetarian',allergens:'Gluten, milk',image:'',available:true},
 {id:'5',name:'Classic cappuccino',category:'Drinks',description:'A double shot of coffee, silky milk and a moment to slow down.',price:180,diet:'Vegetarian',allergens:'Milk',image:'',available:true},
 {id:'6',name:'Iced peach tea',category:'Drinks',description:'Fresh-brewed tea, peach and a squeeze of lemon.',price:160,diet:'Vegan',allergens:'',image:'',available:true}
];
const demoVenue={id:'demo',name:'The Olive Table',slug:'demo',tagline:'Fresh plates. Familiar faces.',address:'A little neighbourhood escape · Hyderabad',accent:'#e6a16a',currency:'INR',wifi_enabled:true,wifi_ssid:'Olive Table · Guest',wifi_password:'welcometothetable',loyalty_enabled:true,reward_target:6,reward_name:'A coffee on the house',published:true,menu:sampleMenu,google_url:'',instagram_url:'',logo_url:'',cover_url:''};
const date=s=>new Date(s).toLocaleDateString('en-IN',{day:'numeric',month:'short'});
const cash=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:selected?.currency||'INR',maximumFractionDigits:2}).format(Number(n)||0);
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function check(r){if(r.error)throw r.error;return r.data;}
function showDialog(html){$('#dialog-body').innerHTML=html;$('#dialog').showModal();}
function qr(target,value,size=180){const el=document.getElementById(target);if(el){el.innerHTML='';new QRCode(el,{text:value,width:size,height:size,colorDark:'#1d231b',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.H});}}
function guestURL(v){return localDemo?`${location.origin}/restaurants/?venue=demo&preview=${encodeURIComponent(v.id)}`:`${location.origin}/restaurants/?venue=${encodeURIComponent(v.slug)}`;}
function field(name,label,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${E(value)}" ${extra}></label>`;}
function selectField(name,label,values,current){return `<label>${label}<select name="${name}">${values.map(x=>`<option ${x===current?'selected':''}>${E(x)}</option>`).join('')}</select></label>`;}
async function api(data){const r=await fetch('/api/restaurant',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({venue_id:selected?.id,...data})});const d=await r.json();if(!r.ok)throw Error(d.error||'Please try again');return d;}
function track(event){if(!demo)api({action:'event',event}).catch(()=>{});}
function login(error=''){
 $('#app').innerHTML=`<main class="auth"><section>${brand}<div class="eyebrow spacer">BUILT FOR INDEPENDENT RESTAURANTS</div><h1>Your whole restaurant.<br><em>One lovely little QR.</em></h1><p class="sub">The menu they came for. The connection they come back for.<br>Give every restaurant a branded page, loyalty card and a way to listen.</p><div class="features"><span>Digital menus</span><span>Guest Wi-Fi</span><span>Loyalty</span><span>Feedback & reviews</span></div><a class="btn light spacer" href="/restaurants/?venue=demo">Explore the guest experience ↗</a></section><section class="auth-visual"><span class="eyebrow">YOUR RESTAURANT WORKSPACE</span><h2 class="spacer">Welcome to the table.</h2><p class="sub">Agents and admins: your existing QR login works here. Restaurant managers: sign in with the account created during setup.</p><form id="login" class="stack">${field('email','Email address','','email','required autocomplete="email"')}${field('password','Password','','password','required autocomplete="current-password"')}<button class="btn full">Sign in to your workspace →</button><p class="error">${E(error)}</p></form><button data-action="google" class="btn light full spacer">Continue with Google</button><p class="account-note">Managers edit their own restaurant. Agents retain setup credit. Administrators control every restaurant.<br><a href="/">Open QR Field Ops ↗</a></p></section></main>`;
}
async function load(){
 if(localDemo){for(const v of venues)localStorage.setItem('yam-demo-venue:'+v.id,JSON.stringify(v));render();return;}
 [venues,managerAccess,commissions]=await Promise.all([allRows('restaurant_venues'),allRows('restaurant_manager_access'),isManager?Promise.resolve([]):allRows('restaurant_commissions')]);
 if(isAdmin())agentProfiles=check(await sb.from('profiles').select('id,name,email,role,active').order('name')).filter(p=>p.active);else agentProfiles=[profile];
 const ids=venues.map(v=>v.id);
 if(ids.length){const r=await Promise.all([
  sb.from('restaurant_feedback').select('*').in('venue_id',ids).order('created_at',{ascending:false}).limit(1000),
  sb.from('restaurant_members').select('id,venue_id,name,stamps,redemptions,created_at,updated_at').in('venue_id',ids).order('created_at',{ascending:false}).limit(1000),
  sb.from('restaurant_events').select('id,venue_id,event,created_at').in('venue_id',ids).gte('created_at',new Date(Date.now()-30*864e5).toISOString()).limit(10000)
 ]);[feedback,members,events]=r.map(check);}else feedback=members=events=[];
 selected=venues.find(v=>v.id===selected?.id)||venues[0]||null;render();
}
function render(){
 const labels={overview:['Overview',isManager?'Your menu, your style, your restaurant.':'Every restaurant, every setup, clearly accounted for.'],venues:['Restaurant clients','Setup credit stays with the original field agent.'],insights:['Guest insights','Listen to your guests and keep them coming back.'],agents:['Agent performance','See who set up each restaurant and review commission eligibility.'],commissions:['Restaurant commissions','You approve setup commissions and record payments.'],edit:[selected?.name||'Restaurant','Keep your menu and guest page beautifully up to date.']};
 const [title,sub]=labels[page]||labels.overview;
 const nav=isManager?[['overview','overview','My restaurant'],['menu','menu','Menu & photos'],['themes','venue','Themes & style'],['insights','insights','Guest feedback']]:[['overview','overview','Overview'],['venues','venue','Restaurants'],['insights','insights','Guest insights'],['agents','insights',isAdmin()?'Agent performance':'My setup credit'],['commissions','loyalty','Commissions']];
 $('#app').innerHTML=`<aside class="sidebar">${brand}<nav class="nav">${nav.map(([id,ic,name])=>`<button class="${page===id?'active':''}" data-nav="${id}"><span>${icon(ic)}</span>${name}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="promo">${icon('table')}<span class="eyebrow">YOUR RESTAURANT. YOUR WAY.</span><p class="sub spacer">A beautiful menu.<br>A warm welcome.</p></div>${!isManager?'<a class="sub" href="/">↗ Google-review workspace</a>':''}<button class="btn light small" data-action="guide">Manager guide</button><button class="btn light small" data-action="logout">Sign out</button></div></aside><div class="workspace"><header class="topbar"><div><span class="eyebrow">${isManager?'RESTAURANT MANAGER':'RESTAURANT WORKSPACE'}</span><p class="sub">Menu · Themes · Guests</p></div><div class="row"><span class="pill">${isManager?'Restaurant manager':isAdmin()?'Administrator':'Field agent'}</span><div class="avatar">${E((profile?.name||user.email||'Y').slice(0,1).toUpperCase())}</div><button class="link" data-action="logout">Sign out</button></div></header><main class="content"><div class="heading row between"><div><span class="eyebrow">${date(new Date().toISOString())} · YOUR WORKSPACE</span><h1>${E(title)}</h1><p class="sub">${E(sub)}</p></div>${isManager?'<button class="btn light" data-action="guide">How to edit my restaurant</button>':'<button class="btn" data-action="new">＋ Set up Restaurant</button>'}</div>${localDemo?'<div class="demo-banner" style="border-radius:8px;margin-bottom:22px">DEMO WORKSPACE · Changes stay in this browser. No live accounts or commissions are changed.</div>':''}${page==='edit'?editor():page==='insights'?insights():page==='venues'?venuePanel():page==='agents'?agentPanel():page==='commissions'?commissionPanel():isManager?managerOverview():overview()}</main></div>`;
 if(page==='edit'&&tab==='qr'&&selected)qr('venue-qr',guestURL(selected));
}

function metrics(){const avg=feedback.length?(feedback.reduce((s,f)=>s+f.rating,0)/feedback.length).toFixed(1):'—';return `<div class="metrics">${[['Guest scans',events.filter(e=>e.event==='scan').length,'Last 30 days'],['Loyalty members',members.length,'Latest 1,000 members'],['Guest rating',avg,'Private feedback · latest 1,000'],['Live restaurants',venues.filter(v=>v.published).length,`${venues.length} venues in your workspace`]].map(([label,value,note])=>`<div class="metric"><div class="metric-top"><span class="sub">${label}</span><span class="metric-icon">${icon(({"Guest scans":"scan","Loyalty members":"loyalty","Guest rating":"star","Live restaurants":"venue"})[label])}</span></div><span class="value">${value}</span><small>${note}</small></div>`).join('')}</div>`;}
function venuePanel(){return `<section class="panel"><div class="panel-head row between"><h2>Restaurant clients</h2><span class="sub">${venues.length} venues</span></div><div class="venue-list">${venues.length?venues.map(v=>`<div class="venue-row"><div class="venue-icon">${safeImage(v.logo_url)?`<img src="${E(safeImage(v.logo_url))}" alt="" style="width:55px;height:55px;border-radius:13px">`:E(v.name.slice(0,1))}</div><div class="venue-copy"><h3>${E(v.name)}</h3><p>${E(v.address||v.slug)} · ${(v.menu||[]).length} menu items</p></div><span class="pill ${v.suspended||!v.published?'draft':''}">${v.suspended?'Paused':v.published?'Live':'Draft'}</span><button class="btn light small" data-edit="${v.id}">Manage ↗</button></div>`).join(''):`<div class="empty">Set up your first restaurant client.<br>Create its profile, add menus, then publish its own restaurant QR page.<br><button class="btn spacer" data-action="new">Set up Restaurant</button></div>`}</div></section>`;}
function overview(){return `<section class="dashboard-hero"><div class="hero-copy"><span class="eyebrow">GOOD FOOD. GREAT CONNECTIONS.</span><h2>Every table.<br><em>A better experience.</em></h2><p class="sub">Bring your restaurant’s menu, rewards and guest connections together in one beautiful scan.</p><button class="btn light small" data-action="new">Set up a restaurant →</button></div><span class="hero-tag">MADE FOR HOSPITALITY</span></section>${metrics()}<div class="dashboard-cols"><div>${venuePanel()}<section class="panel spacer"><div class="panel-head"><h2>Recent conversations</h2></div>${feedback.length?feedback.slice(0,3).map(f=>feedbackRow(f)).join(''):'<div class="empty">When guests share feedback, you’ll hear it here.</div>'}</section></div><div><section class="panel"><div class="illustration"><div class="qr-art">${Array(25).fill('<i></i>').join('')}</div><h3>One scan.<br>More possibilities.</h3><p class="sub">Menus, Wi-Fi, loyalty and feedback.<br>All in your restaurant’s own style.</p><a class="btn light spacer" href="/restaurants/?venue=demo" target="_blank" rel="noopener">Try the guest page ↗</a></div></section><section class="panel spacer"><div class="panel-head"><h2>A little activity</h2></div><div class="activity">${events.length?events.slice().sort((a,b)=>b.id-a.id).slice(0,5).map(e=>`<div class="activity-item"><i class="dot"></i><div>${E(venues.find(v=>v.id===e.venue_id)?.name||'Restaurant')} · ${E(e.event)}<span>${date(e.created_at)}</span></div></div>`).join(''):'<p class="sub">Publish a restaurant page and put its QR on the table to start seeing activity.</p>'}</div></section></div></div>`;}
function feedbackRow(f){return `<div class="feedback"><div class="row between"><div><span class="stars">${'★'.repeat(f.rating)}${'☆'.repeat(5-f.rating)}</span><span class="sub"> ${E(f.name||'A guest')}</span></div><span class="sub">${date(f.created_at)}</span></div><p>${E(f.message||'Rating only')}</p><div class="row between"><span class="sub">${E(venues.find(v=>v.id===f.venue_id)?.name||'')} ${f.food?'· Food '+f.food+'/5':''} ${f.service?'· Service '+f.service+'/5':''}</span><button class="btn ${f.resolved?'soft':'light'} small" data-resolve="${f.id}" data-value="${!f.resolved}">${f.resolved?'✓ Resolved':'Mark resolved'}</button></div></div>`;}
function insights(){return `${metrics()}<section class="panel"><div class="panel-head row between"><h2>Guest feedback</h2><button class="btn light small" data-action="export">Export CSV ↓</button></div>${feedback.length?feedback.map(feedbackRow).join(''):'<div class="empty">No feedback yet. Every guest can share an honest experience.</div>'}</section>`;}
function editor(){if(!selected)return '<div class="empty">No restaurant is assigned to this account.</div>';const v=selected;return `<div class="row between wrap"><select class="restaurant-select" id="venue-select">${venues.map(x=>`<option value="${x.id}" ${x.id===v.id?'selected':''}>${E(x.name)}</option>`).join('')}</select><div class="row wrap"><span class="pill">${v.suspended?'Paused by admin':v.published?'Published':'Draft page'}</span>${v.published&&!v.suspended?`<a class="btn light small" href="${E(guestURL(v))}" target="_blank" rel="noopener">View guest page ↗</a>`:''}${canManage()?`<button class="btn light small" data-action="publish">${v.published?'Unpublish':'Publish page'}</button>`:''}</div></div><div class="tabs spacer">${[['menu','Menu & photos'],['themes','Themes & style'],['profile','Restaurant profile'],['connect','Wi-Fi & Google review'],['loyalty','Loyalty'],['qr','QR & table card'],['access',isManager?'My account':'Manager & handover']].map(([t,l])=>`<button data-tab="${t}" class="${tab===t?'active':''}">${l}</button>`).join('')}</div>${v.suspended?'<div class="notice-strip">This restaurant is paused. Contact the administrator to restore its page and editing access.</div>':''}<section class="panel">${!canManage()&&!['access','qr'].includes(tab)?`<div class="editor"><h2>Handed over to the restaurant manager.</h2><p class="sub">Your setup credit is retained. The manager now edits the menu, images and themes. Ask the administrator to restore agent support if needed.</p><button class="btn light spacer" data-tab="access">View manager & setup details</button></div>`:tab==='profile'?profileEditor(v):tab==='menu'?menuEditor(v):tab==='themes'?themeEditor(v):tab==='connect'?connectEditor(v):tab==='loyalty'?loyaltyEditor(v):tab==='access'?accessEditor(v):qrEditor(v)}</section>`;}

function uploadField(name,label,value=''){return `<label>${label}<input name="${name}" type="url" value="${E(value)}" placeholder="https://…"><span class="upload-control">${icon('venue')} Upload image<input type="file" accept="image/jpeg,image/png,image/webp" data-upload-target="${name}"></span><small class="sub">JPG, PNG or WebP · up to 5 MB</small>${safeImage(value)?`<img class="upload-preview" src="${E(safeImage(value))}" alt="${E(label)}">`:''}</label>`;}
function safeImage(value){return (localDemo||demo)&&/^data:image\/(jpeg|png|webp);base64,/.test(String(value||''))?value:safeURL(value);}
function profileEditor(v){return `<form id="profile-form" class="editor stack"><h3>Your restaurant, at a glance.</h3><div class="grid2">${field('name','Restaurant name',v.name,'text','required maxlength="120"')}${field('tagline','A short welcome',v.tagline)}</div>${field('address','Address / location',v.address)}<div class="grid2">${uploadField('logo_url','Restaurant logo',v.logo_url)}${uploadField('cover_url','Restaurant cover photo',v.cover_url)}</div><div class="grid2">${field('accent','Brand accent',v.accent,'color')}${selectField('currency','Menu currency',['INR','AED','GBP','USD','EUR'],v.currency)}</div><p class="sub">Your permanent guest link stays the same: ${E(guestURL(v))}</p><button class="btn">Save restaurant profile</button></form>`;}

function menuEditor(v){return `<div class="panel-head row between"><div><h2>Your digital menu</h2><p class="sub">${v.menu.length} dishes · Add photos, set prices and keep availability current.</p></div><button class="btn small" data-action="add-item">＋ Add dish</button></div><div class="menu-management">${v.menu.map((i,index)=>`<article class="dish-management"><div class="dish-thumbnail">${safeImage(i.image)?`<img src="${E(safeImage(i.image))}" alt="${E(i.name)}" loading="lazy">`:icon('menu')}</div><div class="dish-copy"><span class="eyebrow">${E(i.category)}</span><h3>${E(i.name)}</h3><p class="sub">${E(i.description||'Add a short description to tempt your guests.')}</p><b>${cash(i.price)}</b><span class="pill">${i.available===false?'Sold out':i.diet||'Available'}</span></div><div class="dish-actions"><button class="btn light small" data-item="${E(i.id)}">Edit dish & photo</button><button class="link" data-available="${E(i.id)}">${i.available===false?'Mark available':'Mark sold out'}</button><div class="row"><button class="link" data-move="${E(i.id)}" data-direction="-1" ${index===0?'disabled':''} aria-label="Move ${E(i.name)} up">↑</button><button class="link" data-move="${E(i.id)}" data-direction="1" ${index===v.menu.length-1?'disabled':''} aria-label="Move ${E(i.name)} down">↓</button><button class="link" data-remove-item="${E(i.id)}">Remove</button></div></div></article>`).join('')||'<div class="empty">Your menu starts with one good dish.<br>Add a name, price, category and an optional photo.</div>'}</div>`;}

function connectEditor(v){return `<form id="connect-form" class="editor stack"><h3>A warm welcome. An honest conversation.</h3>${field('google_url','Google review link',v.google_url,'url')}${field('instagram_url','Restaurant Instagram link',v.instagram_url,'url')}<p class="sub">Every guest sees the same Google review option, whatever feedback rating they give. Public reviews are optional and unrewarded.</p><label class="check"><input name="wifi_enabled" type="checkbox" ${v.wifi_enabled?'checked':''}>Enable guest Wi-Fi</label><div class="grid2">${field('wifi_ssid','Guest network name',v.wifi_ssid)}${field('wifi_password','Guest network password',v.wifi_password)}</div><p class="sub">Use a dedicated guest network. Publishing Wi-Fi makes these credentials visible to anyone with this restaurant link.</p><button class="btn">Save guest connections</button></form>`;}
function loyaltyEditor(v){const list=members.filter(m=>m.venue_id===v.id);return `<form id="loyalty-form" class="editor stack"><h3>Give them a reason to come back.</h3><label class="check"><input type="checkbox" name="loyalty_enabled" ${v.loyalty_enabled?'checked':''}>Enable loyalty cards</label><div class="grid2">${field('reward_name','The reward',v.reward_name,'text','required')}${field('reward_target','Stamps needed',v.reward_target,'number','required min="2" max="30"')}</div><p class="sub">Staff add a stamp after a qualifying purchase and redeem rewards here. Guests cannot award themselves stamps. Cards are saved in their phone browser.</p><button class="btn">Save loyalty programme</button></form><div class="panel-head"><h2>Loyalty members</h2><p class="sub">Match the full card ID shown on the guest’s phone before stamping.</p></div><div class="table-wrap"><table><thead><tr><th>Member / card ID</th><th>Stamps</th><th>Rewards redeemed</th><th>Staff actions</th></tr></thead><tbody>${list.map(m=>`<tr><td>${E(m.name)}<small>${m.id}</small></td><td>${m.stamps} / ${v.reward_target}</td><td>${m.redemptions}</td><td><button class="btn light small" data-stamp="${m.id}" ${m.stamps>=v.reward_target?'disabled':''}>＋ Stamp</button> <button class="btn soft small" data-redeem="${m.id}" ${m.stamps<v.reward_target?'disabled':''}>Redeem</button></td></tr>`).join('')}</tbody></table></div>${list.length?'':'<div class="empty">New loyalty members will appear here.</div>'}`;}
function qrEditor(v){return `<div id="print-card" class="card-preview"><span class="eyebrow" style="color:#dce5d4">RESTAURANT QR · WELCOME TO OUR TABLE</span><h2>${E(v.name)}</h2><p class="sub" style="color:#ccd8c6">Menu · Wi-Fi · Loyalty · Feedback</p><div id="venue-qr" class="qr"></div><strong>Scan. Settle in. Enjoy.</strong><p class="sub" style="color:#ccd8c6;margin-top:12px">No app needed.</p></div><div class="print-note"><p class="sub">${E(guestURL(v))}<br>${agentDemo?'Demo QR works in this browser only.':v.published?'This QR is live.':'Publish this restaurant before using its QR.'} Restaurant QR ID: REST-${v.id.slice(0,8).toUpperCase()}. Your link stays the same when you update the menu.</p><div class="row wrap" style="justify-content:center;margin-top:16px"><button class="btn" data-action="print">Print table card</button><button class="btn light" data-action="download-qr">Download QR PNG ↓</button><button class="btn light" data-action="copy-url">Copy link</button></div></div>`;}
function newVenue(){
 setupStep=1;
 showDialog(`<span class="eyebrow">AGENT RESTAURANT SETUP</span><h2 class="spacer">Set up your restaurant client.</h2><div class="setup-progress" aria-label="Setup progress"><span data-progress="1" class="active">1 · Restaurant</span><span data-progress="2">2 · Branding</span><span data-progress="3">3 · Guest features</span></div><form id="new-venue" class="stack">
 <section data-setup-step="1" class="stack">${field('name','Restaurant name','','text','required maxlength="120"')}${field('slug','Permanent restaurant page name','','text','required pattern="[a-z0-9][a-z0-9-]{2,59}" placeholder="olive-table-hyderabad"')}<p class="sub">Use lowercase letters, numbers and hyphens. This creates a permanent restaurant QR link.</p>${field('address','Restaurant address / location','','text','maxlength="250"')}${field('tagline','Restaurant welcome message','Good food. Great company.','text','maxlength="250"')}</section>
 <section data-setup-step="2" class="stack" hidden>${selectField('restaurant_type','Restaurant type',themes.map(t=>t.type),'Bistro')}<label>Guest page theme<select name="theme">${themes.map(t=>`<option value="${t.id}">${E(t.name)}</option>`).join('')}</select></label><div class="setup-theme-swatches">${themes.map(t=>`<span style="background:${t.accent}" title="${E(t.name)}"></span>`).join('')}</div><div class="grid2">${field('logo_url','Restaurant logo URL (HTTPS)','','url')}${field('cover_url','Cover image URL (HTTPS)','','url')}</div><div class="grid2">${field('accent','Brand colour','#d99b69','color')}${selectField('currency','Menu currency',['INR','AED','GBP','USD','EUR'],'INR')}</div>${field('instagram_url','Restaurant Instagram URL (optional)','','url')}<p class="sub">The restaurant page uses this business’s own name, logo, colours and menu currency.</p></section>
 <section data-setup-step="3" class="stack" hidden><label class="check"><input name="wifi_enabled" type="checkbox">Enable guest Wi-Fi</label><div class="grid2">${field('wifi_ssid','Guest Wi-Fi network')}${field('wifi_password','Guest Wi-Fi password')}</div><label class="check"><input name="loyalty_enabled" type="checkbox" checked>Enable loyalty stamps</label><div class="grid2">${field('reward_name','Loyalty reward','A coffee on the house','text','required')}${field('reward_target','Stamps to earn reward',6,'number','required min="2" max="30"')}</div>${field('google_url','Restaurant’s Google review URL (optional)','','url')}<p class="sub">This is an optional link on the restaurant page. Restaurant setup creates no Google-review QR inventory record.<br>Only use a dedicated guest Wi-Fi network; its password becomes visible on the restaurant page when published.</p></section>
 <div class="form-actions"><button class="btn light" type="button" data-action="setup-back" hidden>← Back</button><button class="btn" type="button" data-action="setup-next">Next →</button><button class="btn" type="submit" id="setup-create" hidden>Create restaurant & manager access →</button></div></form>`);
}
function showSetupStep(){document.querySelectorAll('[data-setup-step]').forEach(x=>x.hidden=Number(x.dataset.setupStep)!==setupStep);document.querySelectorAll('[data-progress]').forEach(x=>x.classList.toggle('active',Number(x.dataset.progress)===setupStep));$('[data-action="setup-back"]').hidden=setupStep===1;$('[data-action="setup-next"]').hidden=setupStep===3;$('#setup-create').hidden=setupStep!==3;}
function validateSetupStep(){const step=document.querySelector(`[data-setup-step="${setupStep}"]`);for(const input of step.querySelectorAll('input,select'))if(!input.reportValidity())return false;return true;}

function itemDialog(id){const i=selected.menu.find(x=>x.id===id)||{id:crypto.randomUUID(),category:'Mains',price:0,available:true};showDialog(`<h2>${id?'Edit your dish':'Something delicious.'}</h2><form id="menu-item" data-id="${E(i.id)}" class="stack"><div class="grid2">${field('name','Dish name',i.name,'text','required maxlength="120"')}${field('category','Menu category',i.category,'text','required maxlength="60"')}</div><label>Description<textarea name="description" rows="2" maxlength="400">${E(i.description)}</textarea></label><div class="grid2">${field('price',`Price (${selected.currency})`,i.price,'number','required min="0" step="0.01"')}${selectField('diet','Dietary label',['','Vegetarian','Vegan','Gluten-free'],i.diet||'')}</div>${field('allergens','Allergens (confirm with the kitchen)',i.allergens,'text','maxlength="250"')}${uploadField('image','Dish photo',i.image)}<label class="check"><input type="checkbox" name="available" ${i.available!==false?'checked':''}>Available to order</label><button class="btn">Save menu item</button></form>`);}
async function save(values){if(!canManage())throw Error('Restaurant editing is managed by its manager or administrator.');if(localDemo){Object.assign(selected,values);}else check(await sb.from('restaurant_venues').update(values).eq('id',selected.id).select().single());await load();toast(localDemo?'Saved in this demo.':'Saved. Your guest page is up to date.');}
function guestRender(){const v=selected;document.documentElement.style.setProperty('--accent',v.accent);document.title=`${v.name} · YAM Table`;document.body.dataset.guestTheme=themeById(v.theme).id;
 $('#app').innerHTML=`<div class="guest-bg"><main class="guest ${guestPage==='home'?'guest-home':'guest-detail'}">${demo?'<div class="demo-banner">DEMO RESTAURANT · Try the experience. No real orders or rewards.</div>':''}${guestPage==='home'?`<div class="guest-cover ${safeImage(v.cover_url)?'has-image':''}">${safeImage(v.cover_url)?`<img src="${E(safeImage(v.cover_url))}" alt="">`:''}<div class="cover-note"><span class="eyebrow">PULL UP A CHAIR</span><p>Good food.<br>Better company.</p><span>Menu · Wi-Fi · Rewards</span></div></div>`:''}<div class="guest-body">${guestPage!=='home'?`<div class="guest-header"><button class="back" data-guest="home">← Back to your table</button><span class="eyebrow">${E(v.name)}</span></div>`:''}${guestPage==='home'?guestHome(v):guestPage==='menu'?guestMenu(v):guestPage==='wifi'?guestWifi(v):guestPage==='loyalty'?guestLoyalty(v):guestPage==='thanks'?guestThanks(v):guestFeedback(v)}<footer class="guest-footer">A little more connection, powered by <a href="/restaurants/">YAM Table</a><br><button class="link" data-action="privacy">Privacy & your data</button>${v.instagram_url?` · <a href="${E(safeURL(v.instagram_url))}" target="_blank" rel="noopener noreferrer">Instagram ↗</a>`:''}</footer></div></main></div>`;
 if(guestPage==='loyalty'&&card)qr('member-qr',card.id,164);
}
function guestHome(v){return `<div class="guest-logo">${safeImage(v.logo_url)?`<img src="${E(safeImage(v.logo_url))}" alt="Restaurant logo">`:E(v.name.slice(0,1))}</div><span class="eyebrow">WELCOME. MAKE YOURSELF AT HOME.</span><h1>${E(v.name)}</h1><p class="sub">${E(v.tagline)}<br>${E(v.address)}</p><div class="guest-links"><button class="guest-link primary" data-guest="menu"><span class="icon">${icon('menu')}</span><div><b>Made to savour</b><small>Explore our menu →</small></div></button>${v.loyalty_enabled?`<button class="guest-link" data-guest="loyalty"><span class="icon">${icon('loyalty')}</span><b>Your next little treat</b><small>Loyalty & rewards →</small></button>`:''}${v.wifi_enabled?`<button class="guest-link" data-guest="wifi"><span class="icon">${icon('wifi')}</span><b>Stay connected</b><small>Our guest Wi-Fi →</small></button>`:''}<button class="guest-link" data-guest="feedback"><span class="icon">${icon('feedback')}</span><b>How was your visit?</b><small>Share a little feedback →</small></button>${v.google_url?`<a class="guest-link" data-track="review" href="${E(safeURL(v.google_url))}" target="_blank" rel="noopener noreferrer"><span class="icon">${icon('star')}</span><b>Share on Google</b><small>Leave an honest review ↗</small></a>`:''}</div><p class="sub" style="text-align:center">Good moments are better shared.</p>`;}
function guestMenu(v){const cats=['All',...new Set(v.menu.map(x=>x.category))];const items=v.menu.filter(i=>(category==='All'||i.category===category));return `<span class="eyebrow">FRESHLY MADE. THOUGHTFULLY SERVED.</span><h2>Something for your table.</h2><input id="menu-search" type="search" placeholder="Find a dish or ingredient" aria-label="Search menu"><div class="category">${cats.map(c=>`<button data-category="${E(c)}" class="${category===c?'active':''}">${E(c)}</button>`).join('')}</div><div id="menu-items">${items.length?items.map(menuRow).join(''):'<div class="empty">The kitchen is preparing its menu.<br>Please ask your server for today’s dishes.</div>'}</div><p class="sub spacer">Please tell your server about any allergies. Menu prices are displayed in ${E(v.currency)}. Ask staff about applicable taxes.</p>`;}
function menuRow(i){return `<article class="menu-item" data-search="${E([i.name,i.description,i.category,i.diet,i.allergens].join(' ').toLowerCase())}"><div><h3>${E(i.name)}</h3><p>${E(i.description)}</p>${i.diet?`<span class="diet">${E(i.diet)}</span>`:''}${i.available===false?'<span class="diet" style="color:#a44b32">Sold out today</span>':`<b>${cash(i.price)}</b>`}${i.allergens?`<span class="allergens">Allergens: ${E(i.allergens)}</span>`:''}</div>${safeImage(i.image)?`<img src="${E(safeImage(i.image))}" alt="${E(i.name)}" loading="lazy">`:''}</article>`;}
function guestWifi(v){return `<span class="eyebrow">MAKE YOURSELF AT HOME</span><h2>A little connection.</h2><p class="sub">Select this network in your phone’s Wi-Fi settings.</p><div class="wifi-box"><span class="eyebrow">NETWORK</span><b>${E(v.wifi_ssid)}</b><span class="eyebrow">PASSWORD</span><b>${E(v.wifi_password||'No password needed')}</b></div><button class="btn full" data-action="copy-wifi">Copy Wi-Fi password</button><button class="btn light full spacer" data-action="wifi-qr">Show Wi-Fi QR</button><p class="sub spacer">A camera can scan the Wi-Fi QR on supported phones. Browser pages cannot connect your phone automatically.</p>`;}
function guestLoyalty(v){return `<span class="eyebrow">GOOD COMPANY DESERVES A THANK YOU</span><h2>Your next treat is closer.</h2><p class="sub">Collect ${v.reward_target} stamps after qualifying purchases for ${E(v.reward_name.toLowerCase())}. Ask staff for the purchase terms.</p>${card?`<div class="loyalty-pass"><span class="eyebrow">${E(v.name)}</span><h3>${E(card.name)}’s little rewards</h3><div class="stamp-grid">${Array.from({length:v.reward_target},(_,i)=>`<span class="stamp ${i<card.stamps?'full':''}">${i<card.stamps?'✓':i+1}</span>`).join('')}</div><p>${card.stamps>=v.reward_target?'Your treat is ready. Ask your server to redeem it.':`${v.reward_target-card.stamps} more stamps until your next treat.`}</p><p class="sub spacer">${E(v.reward_name)}</p></div><section class="member-identification"><span class="eyebrow">YOUR MEMBER QR</span><p class="sub">Show this code to your server to match your loyalty card. Only restaurant staff can add stamps or redeem rewards.</p></section><div id="member-qr" class="qr" style="border:1px solid var(--line)"></div><p class="sub" style="text-align:center;font-size:10px;overflow-wrap:anywhere">Card ID: ${card.id}</p><button class="btn light full spacer" data-action="refresh-card">Refresh my stamps ↻</button><p class="account-note">Keep this browser’s data to retain your card. Clearing it or changing devices can lose access.</p>`:`<form id="join" class="stack">${field('name','Your first name','','text','required maxlength="100" placeholder="What should we call you?"')}<p class="sub">We use your first name and a random card ID to manage your rewards. No marketing messages or email address needed.</p><button class="btn">Create my loyalty card →</button></form>`}`;}
function guestFeedback(){return `<span class="eyebrow">WE’RE ALL EARS</span><h2>How was your visit?</h2><p class="sub">The good bits. The things we can do better.<br>Your feedback goes privately to the restaurant.</p><form id="feedback-form" class="stack"><label>Your overall experience</label><div class="rating-buttons" aria-label="Overall rating">${[1,2,3,4,5].map(n=>`<button type="button" data-rating="${n}" aria-label="${n} star${n>1?'s':''}" aria-pressed="${n===rating}" class="${n<=rating?'active':''}">★</button>`).join('')}</div><div class="grid2">${selectField('food','Food (optional)',['','1','2','3','4','5'],'')}${selectField('service','Service (optional)',['','1','2','3','4','5'],'')}</div><label>A little more about your experience<textarea name="message" rows="4" maxlength="2000" placeholder="Tell us what made your visit memorable…"></textarea></label>${field('name','Your name (optional)','','text','maxlength="100"')}<button class="btn">Send private feedback →</button></form>${selected.google_url?`<a class="btn light full spacer" data-track="review" href="${E(safeURL(selected.google_url))}" target="_blank" rel="noopener noreferrer">Or leave an honest Google review ↗</a>`:''}`;}
function guestThanks(v){return `<div class="success-mark">♡</div><h2>Thank you for sharing.</h2><p class="sub">Your feedback has reached ${E(v.name)}.<br>It helps make the next visit a little better.</p>${v.google_url?`<a class="btn full spacer" data-track="review" href="${E(safeURL(v.google_url))}" target="_blank" rel="noopener noreferrer">Share an honest review on Google ↗</a>`:''}<button class="btn light full spacer" data-guest="home">Back to your table</button>`;}
async function refreshCard(){const token=localStorage.getItem('yam-card:'+selected.id);if(!token){card=null;return;}if(demo){card=JSON.parse(token);return;}card=(await api({action:'card',token})).card;}
function themeEditor(v){return `<div class="editor"><div class="row between wrap"><div><span class="eyebrow">SIX WAYS TO SET YOUR TABLE</span><h2>Find your restaurant’s style.</h2><p class="sub">Choose a theme that suits your food and atmosphere. Your menu, images and QR link stay the same.</p></div><span class="pill">Current: ${E(themeById(v.theme).name)}</span></div><div class="theme-grid">${themes.map(t=>`<article class="theme-card ${v.theme===t.id?'selected':''}"><div class="theme-mini theme-${t.id}"><span class="mini-label">${E(t.badge)}</span><strong style="font-family:'${t.font}',serif">${E(t.name)}</strong><span>A good place to gather.</span><div class="mini-menu"><i></i><div><b>The chef’s favourite</b><small>Freshly made, just for you.</small></div><b>420</b></div><div class="mini-menu"><i></i><div><b>Something to sip</b><small>A little moment to yourself.</small></div><b>180</b></div><span class="mini-cta">Explore our menu →</span></div><div class="theme-info"><div class="row between"><h3>${E(t.name)}</h3>${v.theme===t.id?'<span class="theme-selected">✓ Selected</span>':''}</div><p class="sub">${E(t.description)}</p><span class="theme-font">${E(t.font)} · ${E(t.badge)}</span><button class="btn ${v.theme===t.id?'light':''} full" data-theme-choice="${t.id}" ${v.theme===t.id?'disabled':''}>${v.theme===t.id?'Your current theme':'Use '+E(t.name)}</button></div></article>`).join('')}</div></div>`;}
function managerOverview(){if(!selected)return '<section class="panel empty">No restaurant is linked to this account. Contact your agent or administrator.</section>';const v=selected;return `<section class="manager-welcome"><div><span class="eyebrow">WELCOME TO YOUR RESTAURANT</span><h2>${E(v.name)}</h2><p class="sub">Make it yours. Keep it fresh. Give every guest a lovely welcome.</p><div class="row wrap spacer"><span class="pill">${v.suspended?'Paused':v.published?'Guest page live':'Not published yet'}</span><span class="pill">${E(themeById(v.theme).name)}</span>${v.published&&!v.suspended?`<a class="btn light small" href="${E(guestURL(v))}" target="_blank" rel="noopener">View my guest page ↗</a>`:''}</div></div><div class="welcome-mark">${icon('table')}</div></section>${metrics()}<div class="manager-shortcuts">${[['menu','menu','Menu & photos','Add dishes, upload photos, update prices.'],['themes','venue','Themes & style','Choose from six beautiful restaurant themes.'],['connect','star','Google review & Wi-Fi','Connect your Google review page and guest Wi-Fi.'],['loyalty','loyalty','Loyalty & rewards','Stamp guest cards and redeem their rewards.']].map(([id,ic,title,copy])=>`<button class="panel shortcut" data-quick-tab="${id}">${icon(ic)}<h3>${title}</h3><p class="sub">${copy}</p><span>Open →</span></button>`).join('')}</div><section class="panel spacer"><div class="editor"><h3>You’re in control.</h3><p class="sub">Your agent helps you once during setup. From here, you can manage the menu, pictures, themes, Wi-Fi and Google review link yourself.</p><button class="btn light spacer" data-action="guide">Show me how to edit everything →</button></div></section>`;}
function accessEditor(v){const list=managerAccess.filter(a=>a.venue_id===v.id);return `<div class="editor stack"><span class="eyebrow">SETUP & OWNERSHIP</span><h3>${isManager?'Your restaurant account':'Manager access & handover'}</h3><div class="handover-checklist">${[[v.menu.length>0,'Menu added'],[list.some(a=>a.active),'Manager login created'],[v.published,'Guest page published'],[v.agent_support===false,'Handover complete']].map(([done,label])=>`<span class="${done?'done':''}">${done?'✓':'○'} ${label}</span>`).join('')}</div><p class="sub">Set up by ${E(agentName(v.created_by))} · ${v.created_at?date(v.created_at):'Today'}<br>Setup credit stays with this agent when the manager takes over.</p>${list.length?list.map(a=>`<div class="manager-account row between wrap"><div><h3>${E(a.name)}</h3><p class="sub">${E(a.email)} · ${a.active?'Active manager':'Access disabled'}</p></div>${isAdmin()?`<button class="btn light small" data-control="manager-active" data-manager-id="${a.user_id}" data-active="${!a.active}">${a.active?'Disable access':'Restore access'}</button>`:''}</div>`).join(''):''}${!isManager&&(isAdmin()||canManage())&&!list.some(a=>a.active)?`<form id="manager-create" class="stack manager-create"><h3>Create the restaurant’s login.</h3><p class="sub">Use the manager’s own email. This account manages this restaurant and has no field-agent access.</p>${field('name','Manager name','','text','required maxlength="100" autocomplete="name"')}${field('email','Manager email address','','email','required autocomplete="off"')}${field('password','Initial manager password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<p class="sub">Use at least 12 characters. Share the password securely once; the manager can change it in My account. An existing account’s password is never reset here.</p><button class="btn">Create manager account</button></form>`:''}<div class="notice-strip">Manager sign-in: <a href="/restaurants/?manager=1">${E(location.origin)}/restaurants/?manager=1</a><br>Agents and administrators use their existing QR account and session.</div>${v.agent_support&&canManage()?'<button class="btn" data-control="handover">Finish handover to manager</button><p class="sub">Complete this after the manager can edit dishes, photos and themes. Agent editing ends; admin control and setup credit stay available.</p>':''}${isManager?`<form id="password-form" class="stack"><h3>Update your password</h3>${field('password','New password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}${field('confirm','Confirm new password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<button class="btn light">Update my password</button></form>`:''}${isAdmin()?`<section class="admin-controls stack"><span class="eyebrow">ADMINISTRATOR CONTROLS</span><div class="row wrap"><button class="btn ${v.suspended?'':'danger'}" data-control="suspend">${v.suspended?'Restore restaurant':'Pause restaurant'}</button><button class="btn light" data-control="support">${v.agent_support?'End agent editing':'Restore agent support'}</button></div><p class="sub">Pausing hides the guest page and stops manager editing. You retain full editing control.</p><label>Support agent<select id="support-agent">${agentProfiles.filter(p=>p.role==='worker').map(p=>`<option value="${p.id}" ${p.id===v.owner_id?'selected':''}>${E(p.name)}</option>`).join('')}</select></label><button class="btn light" data-action="assign-agent">Assign support agent</button><p class="sub">This changes who can help edit; it does not transfer original setup credit.</p>${managerAccess.length?`<label>Link an existing restaurant manager<select id="existing-manager">${[...new Map(managerAccess.map(a=>[a.user_id,a])).values()].map(a=>`<option value="${a.user_id}">${E(a.name)} · ${E(a.email)}</option>`).join('')}</select></label><button class="btn light" data-action="link-manager">Link manager to this restaurant</button>`:''}</section>`:''}<button class="btn light" data-action="guide">Open the manager guide</button></div>`;}
function agentPanel(){const ids=[...new Set(venues.map(v=>v.created_by))];const people=isAdmin()?[...new Map([...agentProfiles.filter(p=>p.role==='worker'),...ids.map(id=>({id,name:agentName(id)}))].map(p=>[p.id,p])).values()]:[{id:user.id,name:profile.name}];return `<section class="panel"><div class="panel-head row between"><div><h2>${isAdmin()?'Restaurant setups by agent':'Your restaurant setups'}</h2><p class="sub">Counts include every visible setup, including drafts. Eligible setups have an active manager and a published menu.</p></div><button class="btn light small" data-action="export-setups">Export setups CSV ↓</button></div><div class="table-wrap"><table><thead><tr><th>Agent</th><th>Total setups</th><th>Live</th><th>Manager ready</th><th>Handed over</th><th>Approved</th><th>Paid</th></tr></thead><tbody>${people.map(p=>{const list=venues.filter(v=>v.created_by===p.id),records=commissions.filter(c=>c.agent_id===p.id);return `<tr><td>${E(p.name)}<small>${E(p.email||'')}</small></td><td>${list.length}</td><td>${list.filter(v=>v.published&&!v.suspended).length}</td><td>${list.filter(v=>managerAccess.some(a=>a.venue_id===v.id&&a.active)).length}</td><td>${list.filter(v=>v.agent_support===false).length}</td><td>${records.filter(c=>c.status==='approved').length}</td><td>${records.filter(c=>c.status==='paid').length}</td></tr>`;}).join('')||'<tr><td colspan="7">No setups yet.</td></tr>'}</tbody></table></div></section><div class="spacer">${venuePanel()}</div>`;}
function commissionEligible(v){return v.published&&!v.suspended&&v.menu.length>0&&managerAccess.some(a=>a.venue_id===v.id&&a.active);}
function commissionPanel(){const groups=[...new Set(commissions.map(c=>c.currency))];return `${groups.length?`<div class="commission-totals">${groups.map(currency=>`<div class="panel"><span class="eyebrow">${currency}</span><h3>${commissions.filter(c=>c.currency===currency&&c.status==='approved').reduce((n,c)=>n+Number(c.amount),0).toFixed(2)} approved</h3><p class="sub">${commissions.filter(c=>c.currency===currency&&c.status==='paid').reduce((n,c)=>n+Number(c.amount),0).toFixed(2)} recorded as paid</p></div>`).join('')}</div>`:''}<section class="panel"><div class="panel-head"><h2>${isAdmin()?'Review & approve restaurant commissions':'Your restaurant commissions'}</h2><p class="sub">One setup commission per restaurant. Payment is recorded here after you pay the agent using your chosen method.</p></div><div class="table-wrap"><table><thead><tr><th>Restaurant</th><th>Setup agent</th><th>Eligibility</th><th>Commission</th><th>Status</th><th>${isAdmin()?'Admin action':'Updated'}</th></tr></thead><tbody>${venues.map(v=>{const c=commissions.find(c=>c.venue_id===v.id);return `<tr><td>${E(v.name)}<small>${v.created_at?date(v.created_at):'Today'}</small></td><td>${E(agentName(v.created_by))}</td><td><span class="pill">${commissionEligible(v)?'Ready for review':'Setup incomplete'}</span></td><td>${c?`${E(c.currency)} ${Number(c.amount).toFixed(2)}`:'Awaiting admin amount'}</td><td>${E(c?.status||'pending')}<small>${E(c?.note||'')}</small></td><td>${isAdmin()?`<button class="btn light small" data-commission="${v.id}">Review setup</button>`:c?.updated_at?date(c.updated_at):'—'}</td></tr>`;}).join('')||'<tr><td colspan="6">Restaurant setups will appear here automatically.</td></tr>'}</tbody></table></div></section>`;}
function commissionDialog(id){if(!isAdmin())return;const v=venues.find(v=>v.id===id),c=commissions.find(c=>c.venue_id===id);showDialog(`<span class="eyebrow">ADMIN COMMISSION REVIEW</span><h2>${E(v.name)}</h2><p class="sub">Setup agent: ${E(agentName(v.created_by))}<br>${commissionEligible(v)?'Active manager and published menu are ready.':'Approval requires a published menu and active manager access.'}</p><form id="commission-form" data-venue="${v.id}" class="stack"><div class="grid2">${field('amount','Setup commission amount',c?.amount||0,'number','required min="0" step="0.01"')}${selectField('currency','Currency',['INR','AED','GBP','USD','EUR'],c?.currency||v.currency)}</div><label>Status<select name="status">${['pending','approved','paid','rejected'].map(status=>`<option ${status===(c?.status||'pending')?'selected':''} ${!commissionEligible(v)&&['approved','paid'].includes(status)||status==='paid'&&!['approved','paid'].includes(c?.status)?'disabled':''}>${status}</option>`).join('')}</select></label><label>Admin note<textarea name="note" rows="3" maxlength="1000">${E(c?.note||'')}</textarea></label><p class="sub">Save approved first. After paying the agent, select paid to record it. This does not send or transfer money.</p><button class="btn">Save commission decision</button></form>`);}
function exportSetups(){const rows=[['Restaurant','Setup agent','Created','Live','Manager ready','Handed over','Commission status','Amount','Currency'],...venues.map(v=>{const c=commissions.find(c=>c.venue_id===v.id);return [v.name,agentName(v.created_by),v.created_at,v.published&&!v.suspended,managerAccess.some(a=>a.venue_id===v.id&&a.active),v.agent_support===false,c?.status||'pending',c?.amount||'',c?.currency||''];})];const quote=x=>{let value=String(x??'');if(/^[=+@\-\t\r]/.test(value))value="'"+value;return '"'+value.replace(/"/g,'""')+'"';};const url=URL.createObjectURL(new Blob([rows.map(row=>row.map(quote).join(',')).join('\r\n')],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='restaurant-agent-setups.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function managerGuide(){showDialog(`<span class="eyebrow">YOUR QUICK RESTAURANT GUIDE</span><h2>A little guidance. Total confidence.</h2><ol class="guide-steps"><li><b>Update your menu</b><p>Open Menu & photos → Add dish. Enter its name, category, price and description. Edit dishes anytime or mark them sold out.</p></li><li><b>Add your own pictures</b><p>Choose Upload image in the dish editor or Restaurant profile. Select a JPG, PNG or WebP, then save. Add your logo and cover photo the same way.</p></li><li><b>Choose your restaurant theme</b><p>Open Themes & style. Compare six themes, then choose Use theme. Your existing menu and permanent QR link stay in place.</p></li><li><b>Connect Google reviews & Wi-Fi</b><p>Paste your restaurant’s Google review link in Wi-Fi & Google review. Every guest can open it. Add your dedicated guest Wi-Fi if needed.</p></li><li><b>Publish and check your page</b><p>Publish page → View guest page. Put the QR & table card on your tables. Future menu edits appear at the same link.</p></li><li><b>Take over from your field agent</b><p>Sign in with your own manager account, change the initial password in My account, and finish handover once you’re comfortable editing.</p></li></ol><button class="btn full" data-action="close-guide">Got it, let’s get started</button>`);}

async function run(fn){if(busy)return;busy=true;const buttons=[...document.querySelectorAll('button[type=submit],form button:not([type])')].map(button=>({button,disabled:button.disabled}));buttons.forEach(({button})=>button.disabled=true);try{await fn();}catch(e){toast(e.message||'Please try again.');}finally{busy=false;buttons.forEach(({button,disabled})=>{if(button.isConnected)button.disabled=disabled;});}}
document.addEventListener('submit',e=>{const f=e.target;if(!f.id)return;e.preventDefault();const data=Object.fromEntries(new FormData(f));run(async()=>{
 if(f.id==='manager-create'){if(localDemo){managerAccess.push({venue_id:selected.id,user_id:crypto.randomUUID(),name:data.name,email:data.email,active:true});await load();}else{await manageApi({action:'create-manager',...data});await load();}f.reset();toast('Manager account created. Share the login URL and the password securely with the manager.');}
 if(f.id==='commission-form'){const status=data.status;const previous=commissions.find(c=>c.venue_id===f.dataset.venue);const v=venues.find(v=>v.id===f.dataset.venue);if(status==='paid'&&!['approved','paid'].includes(previous?.status))throw Error('Approve this setup first, then record payment.');const payload={...data,venue_id:v.id,agent_id:v.created_by,amount:Number(data.amount),updated_at:new Date().toISOString(),paid_at:status==='paid'?(previous?.paid_at||new Date().toISOString()):null};if(localDemo){commissions=commissions.filter(c=>c.venue_id!==v.id);commissions.push(payload);}else check(await (previous?sb.from('restaurant_commissions').update(payload).eq('venue_id',v.id):sb.from('restaurant_commissions').insert(payload)));$('#dialog').close();await load();toast('Commission record saved. This records payment; it does not transfer funds.');}
 if(f.id==='password-form'){if(data.password!==data.confirm)throw Error('The passwords do not match.');if(!localDemo)check(await sb.auth.updateUser({password:data.password}));f.reset();toast('Password updated.');}
 if(f.id==='login'){const r=await sb.auth.signInWithPassword({email:data.email,password:data.password});if(r.error){login(r.error.message);return;}location.reload();}
 if(f.id==='new-venue'){
 if(data.slug==='demo')throw Error('Please choose another page name');
 for(const k of ['logo_url','cover_url','google_url','instagram_url'])if(data[k]&&!safeImage(data[k]))throw Error('Image and restaurant links must use HTTPS');
 if(f.wifi_enabled.checked&&!data.wifi_ssid.trim())throw Error('Enter the guest Wi-Fi network name.');
 const payload={...data,reward_target:Number(data.reward_target),wifi_enabled:f.wifi_enabled.checked,loyalty_enabled:f.loyalty_enabled.checked,owner_id:user.id,menu:[]};
 const created=localDemo?{...payload,id:crypto.randomUUID(),created_by:user.id,agent_support:true,suspended:false,published:false,created_at:new Date().toISOString()}:check(await sb.from('restaurant_venues').insert(payload).select().single());
 if(localDemo)venues.unshift(created);
 selected=localDemo?created:{id:created.id};$('#dialog').close();page='edit';tab='access';await load();toast('Restaurant created. Create its manager account, then add dishes and publish.');
}
 if(f.id==='profile-form'){for(const k of ['logo_url','cover_url'])if(data[k]&&!safeImage(data[k]))throw Error('Image links must use HTTPS');await save(data);}
 if(f.id==='connect-form'){for(const k of ['google_url','instagram_url'])if(data[k]&&!safeImage(data[k]))throw Error('Links must use HTTPS');await save({...data,wifi_enabled:f.wifi_enabled.checked});}
 if(f.id==='loyalty-form'){await save({...data,reward_target:Number(data.reward_target),loyalty_enabled:f.loyalty_enabled.checked});}
 if(f.id==='menu-item'){if(data.image&&!safeImage(data.image))throw Error('Photo links must use HTTPS');const item={...data,id:f.dataset.id,price:Number(data.price),available:f.available.checked};const menu=selected.menu.filter(i=>i.id!==item.id);const original=selected.menu.findIndex(i=>i.id===item.id);menu.splice(original<0?menu.length:original,0,item);await save({menu});$('#dialog').close();}
 if(f.id==='join'){if(demo){card={id:crypto.randomUUID(),name:data.name,stamps:2,redemptions:0};localStorage.setItem('yam-card:demo',JSON.stringify(card));}else{const result=await api({action:'join',name:data.name});card=result.card;localStorage.setItem('yam-card:'+selected.id,result.token);}guestRender();}
 if(f.id==='feedback-form'){if(!rating)throw Error('Please choose an overall star rating.');if(!demo)await api({action:'feedback',...data,rating,food:data.food?Number(data.food):null,service:data.service?Number(data.service):null});guestPage='thanks';guestRender();}
 });});
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;
 if(b.classList.contains('close')){$('#dialog').close();return;}
 if(b.dataset.nav){if(['menu','themes'].includes(b.dataset.nav)){page='edit';tab=b.dataset.nav;}else page=b.dataset.nav;render();return;}
 if(b.dataset.edit){selected=venues.find(v=>v.id===b.dataset.edit);page='edit';tab=canManage()?'menu':'access';render();return;}
 if(b.dataset.tab){tab=b.dataset.tab;render();return;}
 if(b.dataset.category){category=b.dataset.category;guestRender();return;}
 if(b.dataset.rating){rating=Number(b.dataset.rating);document.querySelectorAll('[data-rating]').forEach(x=>{x.classList.toggle('active',Number(x.dataset.rating)<=rating);x.setAttribute('aria-pressed',String(Number(x.dataset.rating)===rating));});return;}
 if(b.dataset.track)track(b.dataset.track);
 if(b.dataset.guest){run(async()=>{guestPage=b.dataset.guest;if(guestPage==='loyalty')await refreshCard();if(['menu','wifi','loyalty'].includes(guestPage))track(guestPage);guestRender();window.scrollTo(0,0);});return;}
 if(b.dataset.item){itemDialog(b.dataset.item);return;}
 run(async()=>{
 if(b.dataset.themeChoice){const t=themeById(b.dataset.themeChoice);await save({theme:t.id,accent:t.accent});}
 if(b.dataset.quickTab){page='edit';tab=b.dataset.quickTab;render();}
 if(b.dataset.commission)commissionDialog(b.dataset.commission);
 if(b.dataset.move){const menu=[...selected.menu],index=menu.findIndex(i=>i.id===b.dataset.move),next=index+Number(b.dataset.direction);if(next>=0&&next<menu.length){[menu[index],menu[next]]=[menu[next],menu[index]];await save({menu});}}
 if(b.dataset.control){const action=b.dataset.control;if(localDemo){if(action==='handover')selected.agent_support=false;else if(action==='suspend')selected.suspended=!selected.suspended;else if(action==='support')selected.agent_support=!selected.agent_support;else if(action==='manager-active'){const a=managerAccess.find(a=>a.venue_id===selected.id&&a.user_id===b.dataset.managerId);a.active=!a.active;}await load();}else{await manageApi({action,enabled:action==='suspend'?!selected.suspended:!selected.agent_support,user_id:b.dataset.managerId,active:b.dataset.active==='true'});await load();}toast(action==='handover'?'Handover complete. Your setup credit is retained.':'Admin control updated.');}
 if(b.dataset.available){await save({menu:selected.menu.map(i=>i.id===b.dataset.available?{...i,available:i.available===false}:i)});}
 if(b.dataset.removeItem){showDialog(`<h2>Remove this menu item?</h2><p class="sub">It will disappear from the guest menu.</p><button class="btn danger spacer" data-confirm-remove="${E(b.dataset.removeItem)}">Remove item</button>`);}
 if(b.dataset.confirmRemove){await save({menu:selected.menu.filter(i=>i.id!==b.dataset.confirmRemove)});$('#dialog').close();}
 if(b.dataset.resolve){check(await sb.from('restaurant_feedback').update({resolved:b.dataset.value==='true'}).eq('id',b.dataset.resolve));await load();}
 if(b.dataset.stamp||b.dataset.redeem){check(await sb.rpc('restaurant_stamp',{p_member:b.dataset.stamp||b.dataset.redeem,p_action:b.dataset.stamp?'stamp':'redeem'}));await load();toast(b.dataset.stamp?'Stamp added.':'Reward redeemed.');}
 const action=b.dataset.action;
 if(action==='new'&&!isManager)newVenue();
 if(action==='guide')managerGuide();
 if(action==='close-guide')$('#dialog').close();
 if(action==='export-setups')exportSetups();
 if(action==='assign-agent'){const id=$('#support-agent').value;if(localDemo){selected.owner_id=id;selected.agent_support=true;}else await manageApi({action:'assign-agent',user_id:id});await load();toast('Support agent assigned. Original setup credit stays unchanged.');}
 if(action==='link-manager'){if(localDemo){const a=managerAccess.find(a=>a.user_id===$('#existing-manager').value);managerAccess.push({...a,venue_id:selected.id,active:true});}else await manageApi({action:'link-manager',user_id:$('#existing-manager').value});await load();toast('Manager account linked.');}
 if(action==='setup-next'){if(validateSetupStep()){setupStep=Math.min(3,setupStep+1);showSetupStep();}}
 if(action==='setup-back'){setupStep=Math.max(1,setupStep-1);showSetupStep();}
 if(action==='logout'){if(sb)await sb.auth.signOut();location.href='/restaurants/';}
 if(action==='google'){check(await sb.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+'/restaurants/'+(setupRequested?'?setup=1':'')}}));}
 if(action==='publish'){if(!canManage())throw Error('You cannot edit this restaurant.');if(!selected.published&&!selected.menu.length)throw Error('Add at least one menu item before publishing.');await save({published:!selected.published});}
 if(action==='add-item')itemDialog();
 if(action==='print')window.print();
 if(action==='download-qr'){const img=$('#venue-qr img'),canvas=$('#venue-qr canvas');const a=document.createElement('a');a.href=img?.src?.startsWith('data:')?img.src:canvas.toDataURL();a.download=selected.slug+'-qr.png';a.click();}
 if(action==='copy-url'){await navigator.clipboard.writeText(guestURL(selected));toast('Restaurant link copied.');}
 if(action==='copy-wifi'){await navigator.clipboard.writeText(selected.wifi_password);toast('Wi-Fi password copied.');}
 if(action==='wifi-qr'){showDialog('<h2>Connect to guest Wi-Fi.</h2><div id="wifi-qr" class="qr"></div><p class="sub">Scan with a compatible phone camera.</p>');const escWifi=s=>String(s).replace(/([\\;,:"])/g,'\\$1');qr('wifi-qr',`WIFI:T:${selected.wifi_password?'WPA':'nopass'};S:${escWifi(selected.wifi_ssid)};P:${escWifi(selected.wifi_password)};;`);}
 if(action==='refresh-card'){await refreshCard();guestRender();toast('Your card is up to date.');}
 if(action==='privacy'){showDialog(`<h2>Privacy, in plain language.</h2><p class="sub">${E(selected.name)} receives the name and feedback you choose to submit. Loyalty stores your first name, a random card ID, stamp count and reward history. Only authorised staff can view these records or change stamps.<br><br>Your card credential is stored in this browser; keep it private. No marketing contact details are collected. The service counts page visits and feature use without storing your IP in its restaurant database.<br><br>Ask the restaurant to remove your feedback or loyalty record. Google and Instagram have their own privacy policies when you open those links.</p>`);}
 if(action==='export'){const rows=[['Restaurant','Rating','Food','Service','Name','Feedback','Date','Resolved'],...feedback.map(f=>[venues.find(v=>v.id===f.venue_id)?.name,f.rating,f.food,f.service,f.name,f.message,f.created_at,f.resolved])];const clean=x=>{let s=String(x??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const url=URL.createObjectURL(new Blob([rows.map(r=>r.map(clean).join(',')).join('\r\n')],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='restaurant-feedback.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
 });});
document.addEventListener('input',e=>{if(e.target.id==='menu-search'){const q=e.target.value.toLowerCase();document.querySelectorAll('[data-search]').forEach(x=>x.hidden=!x.dataset.search.includes(q));}});
document.addEventListener('change',e=>{
 if(e.target.id==='venue-select'){selected=venues.find(v=>v.id===e.target.value);render();}
 if(e.target.name==='restaurant_type'&&e.target.closest('#new-venue')){const t=themes.find(t=>t.type===e.target.value)||themes[0];e.target.form.theme.value=t.id;e.target.form.accent.value=t.accent;}
 if(e.target.name==='theme'&&e.target.closest('#new-venue'))e.target.form.accent.value=themeById(e.target.value).accent;
 if(e.target.dataset.uploadTarget){const input=e.target,file=input.files[0],form=input.closest('form'),target=form?.elements.namedItem(input.dataset.uploadTarget);if(!file||!target)return;
 run(async()=>{if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choose a JPG, PNG or WebP image.');if(file.size>5*1024*1024)throw Error('Please choose an image smaller than 5 MB.');if(!canManage())throw Error('You cannot upload images for this restaurant.');
 let imageURL;if(localDemo){imageURL=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});}else{const extension={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type];const path=selected.id+'/'+crypto.randomUUID()+'.'+extension;check(await sb.storage.from('restaurant-images').upload(path,file,{contentType:file.type,upsert:false,cacheControl:'31536000'}));imageURL=sb.storage.from('restaurant-images').getPublicUrl(path).data.publicUrl;}
 target.value=imageURL;let preview=target.parentElement.querySelector('.upload-preview');if(!preview){preview=document.createElement('img');preview.className='upload-preview';preview.alt='Uploaded image preview';target.parentElement.append(preview);}preview.src=imageURL;toast('Image ready. Save this form to publish the change.');input.value='';});}
});
(async()=>{try{
 if(slug){selected=demo?(JSON.parse(localStorage.getItem('yam-demo-venue:'+params.get('preview'))||'null')||demoVenue):(await api({action:'venue',slug})).venue;guestRender();return;}
 if(localDemo){user={id:managerDemo?'demo-manager':'demo-agent',email:'demo@example.invalid'};profile={id:user.id,name:managerDemo?'Demo Manager':adminDemo?'Demo Admin':'Demo Agent',role:adminDemo?'admin':'worker',active:true};isManager=managerDemo;venues=[{...demoVenue,id:'11111111-1111-4111-8111-111111111111',theme:'glass-bistro',created_by:'demo-agent',owner_id:'demo-agent',agent_support:!managerDemo,menu:structuredClone(sampleMenu),created_at:new Date().toISOString()}];managerAccess=[{venue_id:venues[0].id,user_id:'demo-manager',name:'Demo Manager',email:'manager@example.invalid',active:true}];agentProfiles=[{id:'demo-agent',name:'Demo Agent',role:'worker',active:true}];selected=venues[0];await load();if(setupRequested&&!isManager)newVenue();return;}
 const r=await fetch('/.netlify/functions/public-config');const c=await r.json();if(!r.ok)throw Error(c.error||'Connection unavailable');
 // Match the established QR app's session key so navigation never asks again.
 const legacyKey='sb-'+new URL(c.supabaseUrl).hostname.split('.')[0]+'-auth-token';
 if(!localStorage.getItem('qr-field-ops-auth')&&localStorage.getItem(legacyKey))localStorage.setItem('qr-field-ops-auth',localStorage.getItem(legacyKey));
 sb=supabase.createClient(c.supabaseUrl,c.supabasePublishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,flowType:'implicit',storage:window.localStorage,storageKey:'qr-field-ops-auth'}});
 sb.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT'&&user)location.replace('/restaurants/');});
 const sess=check(await sb.auth.getSession());user=sess.session?.user;
 if(!user){login();return;}
 profile=check(await sb.from('profiles').select('id,name,role,active').eq('id',user.id).single());
 managerAccess=await allRows('restaurant_manager_access');isManager=user.app_metadata?.account_type==='restaurant_manager';
 if(isManager&&!managerAccess.some(a=>a.user_id===user.id&&a.active))throw Error('Your restaurant access is inactive. Contact the administrator.');
 if(!isManager&&!profile.active)throw Error('Your workspace account is inactive. Contact your administrator.');await load();if(setupRequested&&!isManager)newVenue();
 }catch(e){$('#app').innerHTML=`<div class="loading"><span>YAM Table</span><h2 style="font-size:27px">${E(e.message||'Unable to load this page')}</h2><a class="btn spacer" href="/restaurants/">Open restaurant workspace</a></div>`;}
})();
